-- ============================================================
-- Migration: 20260904000600_update_ira_aspiration_flats.sql
-- Description: Updates the canonical flats inventory for IRA Aspiration
-- according to exact architectural floor plans for Blocks A-E.
-- ============================================================

-- Ensure derive_flat_floor_label handles Ground Floor 'G' prefix properly
CREATE OR REPLACE FUNCTION public.derive_flat_floor_label()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.flat_number ~ '^G' THEN
    NEW.floor_label := 'G';
  ELSIF length(NEW.flat_number) > 2 THEN
    NEW.floor_label := substr(NEW.flat_number, 1, length(NEW.flat_number) - 2);
  ELSE
    NEW.floor_label := NULL;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  v_comm_id UUID := '64cd9fa6-ad3b-40f0-9f1e-6b9f6a6fce06';
  v_payload JSONB := '[{"block":"A","flats":["G1","G2","G4","G5","G6","G7","G8","G9","G10","G11","G12","G13","G14","G15","G17","101","102","104","105","106","107","108","109","110","111","112","113","114","115","116","117","201","202","203","204","205","206","207","208","209","210","211","212","213","214","215","216","217","301","302","303","304","305","306","307","308","309","310","311","312","313","314","315","316","317","401","402","403","404","405","406","407","408","409","410","411","412","413","414","415","416","417","501","502","503","504","505","506","507","508","509","510","511","512","513","514","515","516","517","601","602","603","604","605","606","607","608","609","610","611","612","613","614","615","616","617","701","702","703","704","705","706","707","708","709","710","711","712","713","714","715","716","717","801","802","803","804","805","806","807","808","809","810","811","812","813","814","815","816","817","901","902","903","904","905","906","907","908","909","910","911","912","913","914","915","916","917"]},{"block":"B","flats":["G1","G2","G4","G5","G6","G7","G8","G9","G10","G11","G12","G13","G14","G15","G16","G17","101","102","104","105","106","107","108","109","110","111","112","113","114","115","116","117","201","202","203","204","205","206","207","208","209","210","211","212","213","214","215","216","217","301","302","303","304","305","306","307","308","309","310","311","312","313","314","315","316","317","401","402","403","404","405","406","407","408","409","410","411","412","413","414","415","416","417","501","502","503","504","505","506","507","508","509","510","511","512","513","514","515","516","517","601","602","603","604","605","606","607","608","609","610","611","612","613","614","615","616","617","701","702","703","704","705","706","707","708","709","710","711","712","713","714","715","716","717","801","802","803","804","805","806","807","808","809","810","811","812","813","814","815","816","817","901","902","903","904","905","906","907","908","909","910","911","912","913","914","915","916","917"]},{"block":"C","flats":["G1","G2","G4","G5","G6","G7","G8","G9","G10","G11","G12","G13","G14","G15","G16","G17","101","102","104","105","106","107","108","109","110","111","112","113","114","115","116","117","201","202","203","204","205","206","207","208","209","210","211","212","213","214","215","216","217","301","302","303","304","305","306","307","308","309","310","311","312","313","314","315","316","317","401","402","403","404","405","406","407","408","409","410","411","412","413","414","415","416","417","501","502","503","504","505","506","507","508","509","510","511","512","513","514","515","516","517","601","602","603","604","605","606","607","608","609","610","611","612","613","614","615","616","617","701","702","703","704","705","706","707","708","709","710","711","712","713","714","715","716","717","801","802","803","804","805","806","807","808","809","810","811","812","813","814","815","816","817","901","902","903","904","905","906","907","908","909","910","911","912","913","914","915","916","917"]},{"block":"D","flats":["G1","G2","G4","G5","G6","G7","G8","G9","G10","G11","G12","G13","G14","G15","G16","G17","101","102","104","105","106","107","108","109","110","111","112","113","114","115","116","117","201","202","203","204","205","206","207","208","209","210","211","212","213","214","215","216","217","301","302","303","304","305","306","307","308","309","310","311","312","313","314","315","316","317","401","402","403","404","405","406","407","408","409","410","411","412","413","414","415","416","417","501","502","503","504","505","506","507","508","509","510","511","512","513","514","515","516","517","601","602","603","604","605","606","607","608","609","610","611","612","613","614","615","616","617","701","702","703","704","705","706","707","708","709","710","711","712","713","714","715","716","717","801","802","803","804","805","806","807","808","809","810","811","812","813","814","815","816","817","901","902","903","904","905","906","907","908","909","910","911","912","913","914","915","916","917"]},{"block":"E","flats":["G1","G2","G5","G6","G7","G8","101","102","104","105","106","107","108","201","202","203","204","205","206","207","208","301","302","303","304","305","306","307","308","401","402","403","404","405","406","407","408","501","502","503","504","505","506","507","508","601","602","603","604","605","606","607","608","701","702","703","704","705","706","707","708","801","802","803","804","805","806","807","808","901","902","903","904","905","906","907","908"]}]'::jsonb;
  v_block_record RECORD;
  v_block_id UUID;
  v_flat_text TEXT;
BEGIN
  -- 1. Ensure blocks exist
  FOR v_block_record IN SELECT * FROM jsonb_array_elements(v_payload) LOOP
    INSERT INTO public.community_blocks (community_id, name)
    VALUES (v_comm_id, v_block_record.value->>'block')
    ON CONFLICT (community_id, name) DO UPDATE
      SET archived_at = NULL, updated_at = now()
    RETURNING id INTO v_block_id;

    -- 2. Insert all canonical flats
    FOR v_flat_text IN SELECT jsonb_array_elements_text(v_block_record.value->'flats') LOOP
      INSERT INTO public.community_flats (community_id, block_id, flat_number)
      VALUES (v_comm_id, v_block_id, upper(btrim(v_flat_text)))
      ON CONFLICT (community_id, block_id, flat_number) DO UPDATE
        SET archived_at = NULL, updated_at = now();
    END LOOP;

    -- 3. Archive or delete obsolete flats for this block not in canonical payload
    DELETE FROM public.community_flats f
    WHERE f.community_id = v_comm_id
      AND f.block_id = v_block_id
      AND f.flat_number NOT IN (
        SELECT upper(btrim(jsonb_array_elements_text(v_block_record.value->'flats')))
      )
      AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.flat_id = f.id);

    -- If any resident was attached to an obsolete flat, archive it instead of hard deleting
    UPDATE public.community_flats f
    SET archived_at = now()
    WHERE f.community_id = v_comm_id
      AND f.block_id = v_block_id
      AND f.flat_number NOT IN (
        SELECT upper(btrim(jsonb_array_elements_text(v_block_record.value->'flats')))
      );
  END LOOP;

  -- 4. Sync profile flat_ids for any existing assigned residents
  UPDATE public.profiles p
  SET flat_id = f.id
  FROM public.community_flats f
  WHERE p.community_id = v_comm_id
    AND f.community_id = v_comm_id
    AND p.block_id = f.block_id
    AND (
      p.flat_number = f.flat_number 
      OR p.flat_number = ((SELECT b.name FROM public.community_blocks b WHERE b.id = p.block_id) || '-' || f.flat_number)
    );

END $$;
